from copy import deepcopy


DEFAULTS = {'endpoint': 'http://localhost', 'retry': {'attempts': 3, 'delay_ms': 100}, 'tags': []}


def _validate_endpoint(value):
    if not isinstance(value, str) or not value:
        raise ValueError('endpoint must be a nonempty string')


def _validate_integer(name, value, minimum, maximum):
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise ValueError(f'{name} must be an integer from {minimum} to {maximum}')


def load_settings(overrides=None, env=None):
    """Return independent settings, layering defaults, overrides, then env."""
    result = deepcopy(DEFAULTS)
    if overrides is not None:
        if not isinstance(overrides, dict):
            raise ValueError('overrides must be a dict')
        if overrides.keys() - DEFAULTS.keys():
            raise ValueError('unknown override key')
        if 'endpoint' in overrides:
            _validate_endpoint(overrides['endpoint'])
            result['endpoint'] = overrides['endpoint']
        if 'retry' in overrides:
            retry = overrides['retry']
            if not isinstance(retry, dict):
                raise ValueError('retry must be a dict')
            if retry.keys() - DEFAULTS['retry'].keys():
                raise ValueError('unknown retry key')
            if 'attempts' in retry:
