import re


_KEY_PATTERN = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z')


def parse_args(argv):
    result = {}
    i = 0
    while i < len(argv):
        option = argv[i]
        if option not in ('--set', '--unset'):
            raise ValueError(f"unknown argument: {option}")
        if i + 1 >= len(argv):
            raise ValueError(f"missing operand for {option}")

        operand = argv[i + 1]
        if option == '--set':
            if '=' not in operand:
                raise ValueError("assignment must be KEY=VALUE")
            key, value = operand.split('=', 1)
        else:
            key, value = operand, None

        if not _KEY_PATTERN.fullmatch(key):
            raise ValueError(f"invalid key: {key}")
        if option == '--set':
            result[key] = value
        else:
            result.pop(key, None)
        i += 2
    return result

