from collections.abc import Mapping


DEFAULTS = {
    'endpoint': 'http://localhost',
    'retry': {'attempts': 3, 'delay_ms': 100},
    'tags': [],
}


def _validate_attempts(value):
    if isinstance(value, bool) or not isinstance(value, int) or not 1 <= value <= 10:
        raise ValueError('retry.attempts must be an integer from 1 to 10')


def _validate_delay(value):
    if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 60000:
        raise ValueError('retry.delay_ms must be an integer from 0 to 60000')


def _validate_endpoint(value):
    if not isinstance(value, str) or not value:
        raise ValueError('endpoint must be a nonempty string')


def _validate_overrides(overrides):
    if not isinstance(overrides, dict):
        raise ValueError('overrides must be a dict')
    if set(overrides) - {'endpoint', 'retry', 'tags'}:
        raise ValueError('unsupported override key')
    if 'endpoint' in overrides:
        _validate_endpoint(overrides['endpoint'])
    if 'retry' in overrides:
        retry = overrides['retry']
        if not isinstance(retry, dict) or set(retry) - {'attempts', 'delay_ms'}:
            raise ValueError('retry must be a dict with supported keys')
        if 'attempts' in retry:
            _validate_attempts(retry['attempts'])
        if 'delay_ms' in retry:
            _validate_delay(retry['delay_ms'])
    if 'tags' in overrides:
        tags = overrides['tags']
        if not isinstance(tags, list) or any(not isinstance(tag, str) for tag in tags):
            raise ValueError('tags must be a list of strings')


def load_settings(overrides=None, env=None):
    overrides = {} if overrides is None else overrides
    env = {} if env is None else env
    _validate_overrides(overrides)
    if not isinstance(env, Mapping):
        raise ValueError('env must be a mapping')

    endpoint = env.get('APP_ENDPOINT', overrides.get('endpoint', DEFAULTS['endpoint']))
    _validate_endpoint(endpoint)
    attempts = overrides.get('retry', {}).get('attempts', DEFAULTS['retry']['attempts'])
    if 'APP_ATTEMPTS' in env:
        raw_attempts = env['APP_ATTEMPTS']
        if (
            not isinstance(raw_attempts, str)
            or not raw_attempts
            or any(char not in '0123456789' for char in raw_attempts)
        ):
            raise ValueError('APP_ATTEMPTS must be a decimal-digit string')
        attempts = int(raw_attempts)
    _validate_attempts(attempts)

    retry = dict(DEFAULTS['retry'])
    retry.update(overrides.get('retry', {}))
    retry['attempts'] = attempts
    return {
        'endpoint': endpoint,
        'retry': retry,
        'tags': list(overrides.get('tags', DEFAULTS['tags'])),
    }

