import re


_KEY = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z')


def parse_args(argv):
    result = {}
    i = 0
    while i < len(argv):
        operation = argv[i]
        if operation not in ('--set', '--unset'):
            raise ValueError(f"unknown argument: {operation}")
        if i + 1 >= len(argv):
            raise ValueError(f"missing operand for {operation}")

        operand = argv[i + 1]
        if operation == '--set':
            if '=' not in operand:
                raise ValueError(f"assignment must be KEY=VALUE: {operand}")
            key, value = operand.split('=', 1)
            if not _KEY.fullmatch(key):
                raise ValueError(f"invalid key: {key}")
            result[key] = value
        else:
            if not _KEY.fullmatch(operand):
                raise ValueError(f"invalid key: {operand}")
            result.pop(operand, None)
        i += 2
    return result

